async function clean(index,guided=false){
 if(busy)return;if(world.carrying){toast('Letakkan kotak terlebih dahulu agar tangan bebas untuk membersihkan.');return;}if(values().dirt.cleaned.includes(index))return;
 if(room().id==='home'&&(!values().broom.practiced||!values().mop.practiced)){toast('Selesaikan latihan Sapu dan Pel dengan postur baik terlebih dahulu.');return;}
 if(tool!=='clean'){setTool('clean',false);}
 const d=world.dirts[index];if(guided){world.objects.get('dirt').group=d;world.focus('dirt');}busy=true;world.hands.perform('clean',.7);const projectId=room().id;toast('Membersihkan area…');const baseScale=d.scale.clone();const start=performance.now();
 await new Promise(resolve=>{function step(){const t=clamp((performance.now()-start)/700,0,1);d.scale.copy(baseScale).multiplyScalar(1-t*.9);if(t<1)requestAnimationFrame(step);else resolve();}requestAnimationFrame(step);});
 if(projectId!==room().id){busy=false;return;}values().dirt.cleaned.push(index);d.scale.copy(baseScale);world.update('dirt',values().dirt);busy=false;scoreUI();save();if(selected==='dirt')renderControls();toast(`Area bersih · ${values().dirt.cleaned.length} dari 3 noda selesai.`);tutorial?.event('clean');
}
function setTool(next,announce=true){tool=next;document.querySelectorAll('.tool').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));const hints={inspect:'Inspeksi: arahkan ke objek lalu tekan F, atau klik misi untuk mendekat.',adjust:'Sesuaikan: pilih furnitur untuk mengubah pengaturannya.',clean:'Bersihkan: arahkan crosshair ke noda dan tekan F.',layout:'Tata ruang: pilih furnitur bertanda geser untuk mengatur posisinya.'};if(announce){sound();toast(hints[next]);}if(selected&&next==='clean')selectObject('dirt');else if(selected&&next==='layout')renderControls();}

