function tickVR(dt,time){if(!vrSession)return;for(const c of vrControllers){const source=c.userData.source;if(!source?.gamepad)continue;const axes=source.gamepad.axes,x=axes.length>2?axes[2]:axes[0],y=axes.length>3?axes[3]:axes[1];if(source.handedness==='left'&&(Math.abs(x)>.15||Math.abs(y)>.15)){const cam=world.renderer.xr.getCamera(),q=cam.getWorldQuaternion(new THREE.Quaternion()),forward=new THREE.Vector3(0,0,-1).applyQuaternion(q);forward.y=0;forward.normalize();const right=new THREE.Vector3().crossVectors(forward,new THREE.Vector3(0,1,0));const delta=forward.multiplyScalar(-y*dt*1.25).addScaledVector(right,x*dt*1.25);const pos=cam.getWorldPosition(new THREE.Vector3());if(!world.collision(pos.x+delta.x,pos.z))world.rig.position.x+=delta.x;if(!world.collision(pos.x,pos.z+delta.z))world.rig.position.z+=delta.z;}
  if(source.handedness==='right'&&Math.abs(x)>.7&&time-vrLastTurn>450){const before=world.renderer.xr.getCamera().getWorldPosition(new THREE.Vector3());world.rig.rotation.y-=Math.sign(x)*Math.PI/6;world.rig.updateMatrixWorld(true);const after=world.renderer.xr.getCamera().getWorldPosition(new THREE.Vector3());world.rig.position.x+=before.x-after.x;world.rig.position.z+=before.z-after.z;vrLastTurn=time;}}
 renderVRPanel();}

