 if(!inputBlocked()&&!vrSession){let forward=(keys.has('KeyW')||keys.has('ArrowUp')?1:0)-(keys.has('KeyS')||keys.has('ArrowDown')?1:0)+joystick.y;let strafe=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0)+joystick.x;const len=Math.hypot(forward,strafe);if(len>1){forward/=len;strafe/=len;}if(len>.01){const before=world.camera.position.clone();world.move(strafe,forward,dt,world.carrying||world.mover.active?1.3:room().id==='outdoor'?(keys.has('ShiftLeft')||keys.has('ShiftRight')||mobile?.sprinting?5.4:3.1):2.1);if(tutorial?.index===0){tutorialDistance+=world.camera.position.distanceTo(before);if(tutorialDistance>.35)tutorial.event('move');}}}
